import logging
from . import tmc, tmc_uart, tmc2130
TMC_FREQUENCY = 12000000.0
Registers = {
  'GCONF': 0,  'GSTAT': 1,  'IFCNT': 2,  'SLAVECONF': 3,
  'OTP_PROG': 4,  'OTP_READ': 5,  'IOIN': 6,  'FACTORY_CONF': 7,
  'IHOLD_IRUN': 16,  'TPOWERDOWN': 17,  'TSTEP': 18,  'TPWMTHRS': 19,
  'VACTUAL': 34,  'MSCNT': 106,  'MSCURACT': 107,  'CHOPCONF': 108,
  'DRV_STATUS': 111,  'PWMCONF': 112,  'PWM_SCALE': 113,  'PWM_AUTO': 114}
ReadRegisters = [
 "GCONF", "GSTAT", "IFCNT", "OTP_READ", "IOIN", "FACTORY_CONF", "TSTEP",
 "MSCNT", "MSCURACT", "CHOPCONF", "DRV_STATUS",
 "PWMCONF", "PWM_SCALE", "PWM_AUTO"]
Fields = {}
